-- Fixed, bounded review approval. No credential reads and no Pin dispatch.
begin;
set local statement_timeout='20s';
set local lock_timeout='5s';
select pg_advisory_xact_lock(1617125,13);
create temporary table reviewed_input as select * from jsonb_to_recordset($data$[{"queue_id": "0886e3c6-15e6-495e-853f-bc00f321856f", "shop": "ChicDecorHK", "listing_id": "1323643255", "source_url": "https://www.etsy.com/listing/1323643255/linen-tie-up-curtain-farmhouse-balloon", "category": "Tie-Up & Balloon Shades", "image_url": null, "destination_url": "https://www.etsy.com/listing/1323643255/linen-tie-up-curtain-farmhouse-balloon", "title": "Linen Tie Up Curtain: Farmhouse Balloon Shade", "body": "Linen Tie Up Curtain: Farmhouse Balloon Shade Style: farmhouse, natural. Materials: linen. View details and available options on Etsy.", "handle": "icyndizhang", "mapped": true, "history_count": 0, "review_exists": false, "new_image_url": "https://i.etsystatic.com/32003756/r/il/1a177e/5195980674/il_794xN.5195980674_600h.jpg", "new_title": "Gathered Tie-Up Curtain Panel", "new_body": "Soft gathered folds and adjustable ties create a cottage-style window detail. This ChicDecorHK rod-pocket curtain is sold as one panel. Explore the original listing for available sizes.", "facebook_draft": "A gentle window refresh: this ChicDecorHK tie-up panel combines gathered folds with a rod-pocket top. See the shop for sizes; each order includes one panel. https://www.etsy.com/listing/1323643255/linen-tie-up-curtain-farmhouse-balloon", "board_id": "801218658646993070", "checked_at": "2026-10-18T02:11:01.578989+00:00", "visual_verified": true, "available": true}, {"queue_id": "3727aad2-59bd-4808-9250-65ec868ad4a3", "shop": "MiawoodStudio", "listing_id": "1302262396", "source_url": "https://www.etsy.com/listing/1302262396/black-walnut-wood-clothes-hanger-brass", "category": "Wooden Hangers", "image_url": null, "destination_url": "https://www.etsy.com/listing/1302262396/black-walnut-wood-clothes-hanger-brass", "title": "Black Walnut Wood Clothes Hanger: Brass Hook, Non-Slip", "body": "Black Walnut Wood Clothes Hanger: Brass Hook, Non-Slip Style: minimal, luxury. Materials: walnut_wood, brass. View details and available options on Etsy.", "handle": "sailing_981", "mapped": true, "history_count": 0, "review_exists": false, "new_image_url": "https://i.etsystatic.com/32100253/r/il/6baa55/6174356732/il_794xN.6174356732_ooud.jpg", "new_title": "Walnut Clothes Hanger with Brass Hook", "new_body": "Curved walnut wood and a brass hook bring warm detail to a wardrobe. This MiawoodStudio hanger has naturally varying wood grain. See Etsy for single-hanger and set options.", "facebook_draft": "Warm walnut grain meets a brass hook in this MiawoodStudio clothes hanger. Explore the original listing for quantity options and details. https://www.etsy.com/listing/1302262396/black-walnut-wood-clothes-hanger-brass", "board_id": "863494997243989843", "checked_at": "2026-10-18T02:11:01.579236+00:00", "visual_verified": true, "available": true}, {"queue_id": "00ddc397-2444-46f8-bb9a-21bfb9afc3cd", "shop": "Chtte", "listing_id": "4440783510", "source_url": "https://www.etsy.com/listing/4440783510/u-shaped-chair-cushion-linen-blend-seat", "category": "Chair Cushions & Seat Pads", "image_url": null, "destination_url": "https://www.etsy.com/listing/4440783510/u-shaped-chair-cushion-linen-blend-seat", "title": "U Shaped Chair Cushion, Linen Blend Seat Pad, High Density Foam Dining Pad", "body": "U Shaped Chair Cushion, Linen Blend Seat Pad, High Density Foam Dining Pad Style: minimal, oriental, natural. Materials: linen, cotton, polyester. View details and available options on Etsy.", "handle": "icyndizhang", "mapped": true, "history_count": 0, "review_exists": false, "new_image_url": "https://i.etsystatic.com/58205190/r/il/84a6a5/7862884888/il_794xN.7862884888_c6j4.jpg", "new_title": "Textured U-Shaped Chair Cushion", "new_body": "A rounded seat pad with textured fabric adds a soft detail to dining chairs. This Chtte cushion has a foam insert and tie straps. Check the original listing for size and color options.", "facebook_draft": "Refresh a dining chair with a textured Chtte seat cushion. Tie straps help hold it in place; measure your chair and explore the available sizes in the shop. https://www.etsy.com/listing/4440783510/u-shaped-chair-cushion-linen-blend-seat", "board_id": "801218658646993070", "checked_at": "2026-10-18T02:11:01.579239+00:00", "visual_verified": true, "available": true}, {"queue_id": "1fd1c427-5717-4ba9-bd14-9920e95997d9", "shop": "WoodHomeLiang", "listing_id": "1383474987", "source_url": "https://www.etsy.com/listing/1383474987/handmade-wooden-branch-clothes-hanger", "category": "Wooden Hangers", "image_url": null, "destination_url": "https://www.etsy.com/listing/1383474987/handmade-wooden-branch-clothes-hanger", "title": "Handmade Wooden Branch Clothes Hanger, Natural Wood S Hook", "body": "Handmade Wooden Branch Clothes Hanger, Natural Wood S Hook Style: rustic, natural, handmade. Materials: wood. View details and available options on Etsy.", "handle": "sailing_981", "mapped": true, "history_count": 0, "review_exists": false, "new_image_url": "https://i.etsystatic.com/38928671/r/il/0eebc0/5450392113/il_794xN.5450392113_dnud.jpg", "new_title": "Natural Branch Hangers and Hooks", "new_body": "Natural branch shapes give these WoodHomeLiang hangers and hooks a rustic look. Styles are selected separately, and grain, shape and color vary from piece to piece. Explore the Etsy listing for options.", "facebook_draft": "Bring a natural detail to a hanging rail with branch-inspired wooden hangers and hooks from WoodHomeLiang. Choose your preferred style; each piece varies naturally. https://www.etsy.com/listing/1383474987/handmade-wooden-branch-clothes-hanger", "board_id": "863494997243989843", "checked_at": "2026-10-18T02:11:01.579244+00:00", "visual_verified": true, "available": true}]$data$::jsonb) as x(queue_id uuid,shop text,listing_id text,source_url text,category text,image_url text,destination_url text,title text,body text,handle text,board_id text,new_title text,new_body text,checked_at timestamptz,new_image_url text,facebook_draft text);
select q.id from publish_queue q join reviewed_input x on x.queue_id=q.id for update of q;
select cv.id from content_variants cv join publish_queue q on q.content_variant_id=cv.id join reviewed_input x on x.queue_id=q.id for update of cv;
select p.id from products p join publish_queue q on q.product_id=p.id join reviewed_input x on x.queue_id=q.id for update of p;
do $$
begin
 if not exists(select 1 from pinterest_publish_settings where singleton and enabled and access_tier='standard') then raise exception 'Enabled Standard settings required'; end if;
 if exists(select 1 from reviewed_input where checked_at < now()-interval '24 hours' or checked_at>now()) then raise exception 'Fixed approval expired'; end if;
 if (select count(*) from reviewed_input x join publish_queue q on q.id=x.queue_id join products p on p.id=q.product_id and p.shop_id=q.shop_id join shops s on s.id=q.shop_id join content_variants cv on cv.id=q.content_variant_id and cv.product_id=p.id and cv.shop_id=s.id join social_accounts a on a.id=q.social_account_id
 where q.platform='pinterest' and cv.platform='pinterest' and q.status='draft' and cv.status='draft' and s.status='active' and a.active and a.handle=x.handle and a.platform='pinterest' and s.shop_name=x.shop and p.etsy_listing_id=x.listing_id and p.etsy_url=x.source_url and cv.destination_url=x.destination_url and cv.board_or_category=x.category and cv.image_url is not distinct from x.image_url and cv.title=x.title and cv.body=x.body
 and exists(select 1 from shop_social_accounts m where m.shop_id=s.id and m.social_account_id=a.id and m.platform='pinterest' and m.active)
 and exists(select 1 from pinterest_oauth_credentials cr where cr.social_account_id=a.id and lower(cr.pinterest_username)=lower(a.handle))
 and not exists(select 1 from publish_history h where h.product_id=p.id)
 and not exists(select 1 from pinterest_publish_attempts pa where pa.queue_id=q.id)) <> 4 then raise exception 'Expected 4 unchanged, mapped, unattempted drafts'; end if;
 if exists(select 1 from pinterest_publish_reviews rev join reviewed_input x on rev.queue_id=x.queue_id where rev.board_id<>x.board_id or rev.snapshot<>pinterest_publish_snapshot(x.queue_id)) then raise exception 'Existing review differs'; end if;
end $$;
update products p set listing_status='active',last_seen_at=x.checked_at from publish_queue q join reviewed_input x on x.queue_id=q.id where p.id=q.product_id;
update content_variants cv set status=case when x.board_id is null then 'draft'::content_status else 'ready'::content_status end,title=x.new_title,body=x.new_body,image_url=x.new_image_url from publish_queue q join reviewed_input x on x.queue_id=q.id where cv.id=q.content_variant_id;

update products p set primary_image_url=x.new_image_url,original_image_urls=jsonb_build_array(x.new_image_url),source_payload=coalesce(p.source_payload,'{}'::jsonb)||jsonb_build_object('material_verification',jsonb_build_object('source_url',x.source_url,'verified_at',x.checked_at,'image_verified',true,'batch','daily-20261018-b3')) from publish_queue q join reviewed_input x on x.queue_id=q.id where p.id=q.product_id;
update content_variants cv set image_url=x.new_image_url,title=x.new_title,body=x.facebook_draft
from publish_queue q join reviewed_input x on x.queue_id=q.id where cv.product_id=q.product_id and cv.shop_id=q.shop_id and cv.platform='facebook' and cv.status='draft'
and not exists(select 1 from publish_history h where h.content_variant_id=cv.id)
and not exists(select 1 from publish_queue fq where fq.content_variant_id=cv.id and fq.status<>'draft');

insert into pinterest_publish_reviews(queue_id,board_id,snapshot,listing_checked_at,source_url)
select x.queue_id,x.board_id,pinterest_publish_snapshot(x.queue_id),x.checked_at,x.source_url from reviewed_input x where x.board_id is not null on conflict(queue_id) do nothing;
update publish_queue q set status='ready',updated_at=now() from reviewed_input x where q.id=x.queue_id and q.status='draft' and x.board_id is not null;
select json_build_object('queue_id',q.id,'status',q.status,'board_id',rev.board_id,'snapshot_matches',rev.snapshot=pinterest_publish_snapshot(q.id),'listing_checked_at',rev.listing_checked_at) from publish_queue q join reviewed_input x on x.queue_id=q.id left join pinterest_publish_reviews rev on rev.queue_id=q.id;
select json_build_object('public_publish_enabled',enabled) from pinterest_publish_settings where singleton;


commit;
